const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '1' },
      { kind: 'text', payload: '1' },
      { kind: 'text', payload: '1:1' }
    ];
  },
  render: function (input, metrics) {
    var w = input.viewport.widthDu;
    var h = input.viewport.heightDu;
    var x0 = w * 0.16;
    var x1 = w * 0.84;
    var y = h * 0.56;
    var mid = (x0 + x1) / 2;

    var line = visualSdk.polyline([[x0, y], [x1, y]]);
    var divider = visualSdk.polyline([[mid, y - 20], [mid, y + 20]]);
    var leftTick = visualSdk.polyline([[x0, y - 9], [x0, y + 9]]);
    var rightTick = visualSdk.polyline([[x1, y - 9], [x1, y + 9]]);

    return {
      schemaVersion: 1,
      sceneId: 'equal-segment-ratio',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: w, height: h },
      paths: [
        { id: 'line', commands: line },
        { id: 'divider', commands: divider },
        { id: 'leftTick', commands: leftTick },
        { id: 'rightTick', commands: rightTick }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'line', fill: '#26354a', stroke: { width: 4, cap: 'round', join: 'round' } },
          { type: 'path', pathId: 'divider', fill: '#26354a', stroke: { width: 3, cap: 'round', join: 'round' } },
          { type: 'path', pathId: 'leftTick', fill: '#26354a', stroke: { width: 2, cap: 'round', join: 'round' } },
          { type: 'path', pathId: 'rightTick', fill: '#26354a', stroke: { width: 2, cap: 'round', join: 'round' } },
          { type: 'label', contentId: metrics[0].contentId, anchor: { x: (x0 + mid) / 2, y: y - 28 }, hAlign: 'center', vAlign: 'bottom', color: '#26354a' },
          { type: 'label', contentId: metrics[1].contentId, anchor: { x: (mid + x1) / 2, y: y - 28 }, hAlign: 'center', vAlign: 'bottom', color: '#26354a' },
          { type: 'label', contentId: metrics[2].contentId, anchor: { x: w / 2, y: y + 36 }, hAlign: 'center', vAlign: 'top', color: '#26354a' }
        ]
      }
    };
  }
};
